109	                      <Route path="/jobs" element={<ProtectedRoute><Index /></ProtectedRoute>} />
110	                      <Route path="/profile" element={<ProtectedRoute><Profile /></ProtectedRoute>} />
111	                      <Route path="/billing" element={<ProtectedRoute><Billing /></ProtectedRoute>} />
112	                      <Route path="/settings" element={<ProtectedRoute><Settings /></ProtectedRoute>} />
113	                      <Route path="/team" element={<ProtectedRoute><Team /></ProtectedRoute>} />
114	                      <Route path="/tasks" element={<ProtectedRoute><Tasks /></ProtectedRoute>} />
115	                      <Route path="/career-settings" element={<ProtectedRoute><CareerSettings /></ProtectedRoute>} />
116	                      <Route path="/admin" element={<AdminRoute><Admin /></AdminRoute>} />
117	                      <Route path="/book-demo" element={<BookDemo />} />
118	                      <Route path="/request-feature" element={<RequestFeature />} />
119	                      <Route path="/changelog" element={<Changelog />} />
120	                      <Route path="/payment/callback" element={<PaymentCallback />} />
121	                      <Route path="*" element={<NotFound />} />
122	                    </Routes>
