124	                } />
125	              </Routes>
126	            </Suspense>
127	            <ChatWidget />
128	          </BrowserRouter>
129	        </TooltipProvider>
130	      </AuthProvider>
131	    </ThemeProvider>
132	  </QueryClientProvider>
133	);
134	
135	export default App;
